"""
DataForSEO API client for SEO-AGI.
Handles SERP results, keyword data, People Also Ask, and content parsing.
"""

import json
import base64
import urllib.request
import urllib.error
from typing import Optional


class DataForSEOClient:
    """Client for DataForSEO REST API v3."""

    BASE_URL = "https://api.dataforseo.com/v3"

    def __init__(self, login: str, password: str):
        self.login = login
        self.password = password
        self._auth_header = self._make_auth_header(login, password)

    @staticmethod
    def _make_auth_header(login: str, password: str) -> str:
        token = base64.b64encode(f"{login}:{password}".encode()).decode()
        return f"Basic {token}"

    def _request(self, endpoint: str, payload: list[dict]) -> dict:
        """Make a POST request to DataForSEO API."""
        url = f"{self.BASE_URL}{endpoint}"
        data = json.dumps(payload).encode("utf-8")

        req = urllib.request.Request(
            url,
            data=data,
            headers={
                "Authorization": self._auth_header,
                "Content-Type": "application/json",
            },
            method="POST",
        )

        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.loads(resp.read().decode())
        except urllib.error.HTTPError as e:
            body = e.read().decode() if e.fp else ""
            raise RuntimeError(
                f"DataForSEO API error {e.code}: {body}"
            ) from e
        except urllib.error.URLError as e:
            raise RuntimeError(
                f"DataForSEO connection error: {e.reason}"
            ) from e

    def serp_live(
        self,
        keyword: str,
        location_code: int = 2840,
        language_code: str = "en",
        depth: int = 10,
    ) -> dict:
        """
        Get live SERP results for a keyword.
        Returns organic results with position, URL, title, description.
        """
        payload = [
            {
                "keyword": keyword,
                "location_code": location_code,
                "language_code": language_code,
                "depth": depth,
                "se_type": "organic",
            }
        ]
        result = self._request(
            "/serp/google/organic/live/advanced", payload
        )
        return self._extract_serp(result)

    def related_keywords(
        self,
        keyword: str,
        location_code: int = 2840,
        language_code: str = "en",
        limit: int = 30,
    ) -> list[dict]:
        """Get related keywords with search volume and difficulty."""
        payload = [
            {
                "keyword": keyword,
                "location_code": location_code,
                "language_code": language_code,
                "limit": limit,
            }
        ]
        result = self._request(
            "/dataforseo_labs/google/related_keywords/live", payload
        )
        return self._extract_keywords(result)

    def keyword_suggestions(
        self,
        keyword: str,
        location_code: int = 2840,
        language_code: str = "en",
        limit: int = 30,
    ) -> list[dict]:
        """Get keyword suggestions (broader ideation)."""
        payload = [
            {
                "keyword": keyword,
                "location_code": location_code,
                "language_code": language_code,
                "limit": limit,
            }
        ]
        result = self._request(
            "/dataforseo_labs/google/keyword_suggestions/live", payload
        )
        return self._extract_keywords(result)

    def content_parse(self, url: str) -> Optional[dict]:
        """Parse content from a URL (headings, word count, structure)."""
        payload = [{"url": url}]
        try:
            result = self._request(
                "/on_page/content_parsing/live", payload
            )
            return self._extract_content(result)
        except RuntimeError:
            return None

    def _extract_serp(self, raw: dict) -> dict:
        """Extract clean SERP data from API response."""
        tasks = raw.get("tasks", [])
        if not tasks:
            return {"organic": [], "paa": [], "featured_snippet": None}

        result = tasks[0].get("result", [])
        if not result:
            return {"organic": [], "paa": [], "featured_snippet": None}

        items = result[0].get("items", [])

        organic = []
        paa_questions = []
        featured_snippet = None

        for item in items:
            item_type = item.get("type", "")

            if item_type == "organic":
                organic.append(
                    {
                        "position": item.get("rank_absolute", 0),
                        "url": item.get("url", ""),
                        "domain": item.get("domain", ""),
                        "title": item.get("title", ""),
                        "description": item.get("description", ""),
                    }
                )

            elif item_type == "people_also_ask":
                for paa_item in item.get("items", []):
                    q = paa_item.get("title", "")
                    if q:
                        paa_questions.append(q)

            elif item_type == "featured_snippet":
                featured_snippet = {
                    "url": item.get("url", ""),
                    "title": item.get("title", ""),
                    "description": item.get("description", ""),
                }

        return {
            "organic": organic,
            "paa": paa_questions,
            "featured_snippet": featured_snippet,
            "total_results": result[0].get("se_results_count", 0),
        }

    def _extract_keywords(self, raw: dict) -> list[dict]:
        """Extract keyword data from labs API response."""
        tasks = raw.get("tasks", [])
        if not tasks:
            return []

        result = tasks[0].get("result", [])
        if not result:
            return []

        items = result[0].get("items", [])
        keywords = []

        for item in items:
            kw_data = item.get("keyword_data", item)
            keyword_info = kw_data.get("keyword_info", {})
            keywords.append(
                {
                    "keyword": kw_data.get("keyword", ""),
                    "volume": keyword_info.get("search_volume", 0),
                    "cpc": keyword_info.get("cpc", 0),
                    "competition": keyword_info.get("competition", 0),
                    "difficulty": kw_data.get(
                        "keyword_properties", {}
                    ).get("keyword_difficulty", 0),
                }
            )

        return sorted(keywords, key=lambda x: x["volume"], reverse=True)

    def _extract_content(self, raw: dict) -> Optional[dict]:
        """Extract content structure from on-page parsing."""
        tasks = raw.get("tasks", [])
        if not tasks:
            return None

        result = tasks[0].get("result", [])
        if not result:
            return None

        items = result[0].get("items", [])
        if not items:
            return None

        page = items[0].get("page_content", {})

        return {
            "title": page.get("header", {}).get("title", ""),
            "word_count": page.get("plain_text_word_count", 0),
            "headings": self._extract_headings(page),
            "plain_text_size": page.get("plain_text_size", 0),
        }

    @staticmethod
    def _extract_headings(page_content: dict) -> list[str]:
        """Pull heading tags from parsed content."""
        headings = []
        for level in ["h1", "h2", "h3"]:
            for heading in page_content.get(level, []):
                headings.append(f"{level.upper()}: {heading}")
        return headings

"""Tests for DataForSEO client response parsing."""

import sys
from pathlib import Path

sys.path.insert(
    0, str(Path(__file__).parent.parent / "scripts")
)

from lib.dataforseo import DataForSEOClient


def test_extract_serp_empty():
    client = DataForSEOClient("test", "test")
    result = client._extract_serp({"tasks": []})
    assert result["organic"] == []
    assert result["paa"] == []
    assert result["featured_snippet"] is None


def test_extract_serp_with_organic():
    raw = {
        "tasks": [{
            "result": [{
                "se_results_count": 1000000,
                "items": [
                    {
                        "type": "organic",
                        "rank_absolute": 1,
                        "url": "https://example.com/page",
                        "domain": "example.com",
                        "title": "Test Page",
                        "description": "A test description",
                    },
                    {
                        "type": "organic",
                        "rank_absolute": 2,
                        "url": "https://other.com/page",
                        "domain": "other.com",
                        "title": "Other Page",
                        "description": "Another description",
                    },
                    {
                        "type": "people_also_ask",
                        "items": [
                            {"title": "What is a test?"},
                            {"title": "How do tests work?"},
                        ],
                    },
                ]
            }]
        }]
    }

    client = DataForSEOClient("test", "test")
    result = client._extract_serp(raw)

    assert len(result["organic"]) == 2
    assert result["organic"][0]["position"] == 1
    assert result["organic"][0]["url"] == "https://example.com/page"
    assert result["organic"][1]["title"] == "Other Page"

    assert len(result["paa"]) == 2
    assert result["paa"][0] == "What is a test?"

    assert result["total_results"] == 1000000


def test_extract_keywords_empty():
    client = DataForSEOClient("test", "test")
    result = client._extract_keywords({"tasks": []})
    assert result == []


def test_extract_keywords_with_data():
    raw = {
        "tasks": [{
            "result": [{
                "items": [
                    {
                        "keyword_data": {
                            "keyword": "test keyword one",
                            "keyword_info": {
                                "search_volume": 5000,
                                "cpc": 1.50,
                                "competition": 0.7,
                            },
                            "keyword_properties": {
                                "keyword_difficulty": 42,
                            },
                        }
                    },
                    {
                        "keyword_data": {
                            "keyword": "test keyword two",
                            "keyword_info": {
                                "search_volume": 8000,
                                "cpc": 2.10,
                                "competition": 0.85,
                            },
                            "keyword_properties": {
                                "keyword_difficulty": 55,
                            },
                        }
                    },
                ]
            }]
        }]
    }

    client = DataForSEOClient("test", "test")
    result = client._extract_keywords(raw)

    # Should be sorted by volume descending
    assert len(result) == 2
    assert result[0]["keyword"] == "test keyword two"
    assert result[0]["volume"] == 8000
    assert result[1]["keyword"] == "test keyword one"
    assert result[1]["volume"] == 5000
    assert result[1]["difficulty"] == 42


def test_extract_headings():
    page_content = {
        "h1": ["Main Title"],
        "h2": ["Section One", "Section Two"],
        "h3": ["Subsection A", "Subsection B"],
    }
    headings = DataForSEOClient._extract_headings(page_content)
    assert "H1: Main Title" in headings
    assert "H2: Section One" in headings
    assert "H3: Subsection A" in headings
    assert len(headings) == 5


def test_auth_header():
    client = DataForSEOClient("user@test.com", "mypassword")
    assert client._auth_header.startswith("Basic ")
    assert len(client._auth_header) > 10


if __name__ == "__main__":
    test_extract_serp_empty()
    test_extract_serp_with_organic()
    test_extract_keywords_empty()
    test_extract_keywords_with_data()
    test_extract_headings()
    test_auth_header()
    print("All tests passed.")

"""Tests for env module."""

import sys
import os
import json
import tempfile
from pathlib import Path

sys.path.insert(
    0, str(Path(__file__).parent.parent / "scripts")
)

from lib.env import load_config, _determine_mode, DEFAULT_CONFIG


def test_default_config():
    config = DEFAULT_CONFIG.copy()
    assert config["default_location"] == 2840
    assert config["default_language"] == "en"
    assert config["serp_depth"] == 10
    assert config["save_research"] is True


def test_determine_mode_full():
    creds = {"has_dataforseo": True, "has_gsc": True, "has_ahrefs": False, "has_semrush": False}
    assert _determine_mode(creds) == "full"


def test_determine_mode_dataforseo_only():
    creds = {"has_dataforseo": True, "has_gsc": False, "has_ahrefs": False, "has_semrush": False}
    assert _determine_mode(creds) == "dataforseo-only"


def test_determine_mode_gsc_only():
    creds = {"has_dataforseo": False, "has_gsc": True, "has_ahrefs": False, "has_semrush": False}
    assert _determine_mode(creds) == "gsc-only"


def test_determine_mode_fallback():
    creds = {"has_dataforseo": False, "has_gsc": False, "has_ahrefs": False, "has_semrush": False}
    assert _determine_mode(creds) == "fallback"


if __name__ == "__main__":
    test_default_config()
    test_determine_mode_full()
    test_determine_mode_dataforseo_only()
    test_determine_mode_gsc_only()
    test_determine_mode_fallback()
    print("All tests passed.")
